package com.sit.entity;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.junit.jupiter.params.provider.NullSource;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for Doctor entity class.
 * Tests all getters, setters, constructors, equals, hashCode, and toString
 * generated by Lombok @Data annotation.
 */
@DisplayName("Doctor Entity Tests")
class DoctorTest {

    private Doctor doctor;

    @BeforeEach
    void setUp() {
        doctor = new Doctor();
    }

    // ─── Constructor Tests ───────────────────────────────────────────────────

    @Test
    @DisplayName("Default constructor creates non-null Doctor instance")
    void testDefaultConstructor_createsNonNullInstance() {
        // Arrange & Act
        Doctor doc = new Doctor();

        // Assert
        assertNotNull(doc);
    }

    @Test
    @DisplayName("Default constructor initializes fields to null/default")
    void testDefaultConstructor_fieldsAreNull() {
        // Arrange & Act
        Doctor doc = new Doctor();

        // Assert
        assertNull(doc.getDocId());
        assertNull(doc.getDocName());
        assertNull(doc.getSpecialization());
        assertNull(doc.getIncome());
    }

    // ─── Setter / Getter Tests ───────────────────────────────────────────────

    @Test
    @DisplayName("setDocId and getDocId work correctly")
    void testSetAndGetDocId() {
        // Arrange
        Integer expectedId = 101;

        // Act
        doctor.setDocId(expectedId);

        // Assert
        assertEquals(expectedId, doctor.getDocId());
    }

    @Test
    @DisplayName("setDocName and getDocName work correctly")
    void testSetAndGetDocName() {
        // Arrange
        String expectedName = "Dr. Smith";

        // Act
        doctor.setDocName(expectedName);

        // Assert
        assertEquals(expectedName, doctor.getDocName());
    }

    @Test
    @DisplayName("setSpecialization and getSpecialization work correctly")
    void testSetAndGetSpecialization() {
        // Arrange
        String expectedSpec = "MD_Cardio";

        // Act
        doctor.setSpecialization(expectedSpec);

        // Assert
        assertEquals(expectedSpec, doctor.getSpecialization());
    }

    @Test
    @DisplayName("setIncome and getIncome work correctly")
    void testSetAndGetIncome() {
        // Arrange
        Double expectedIncome = 90000.00;

        // Act
        doctor.setIncome(expectedIncome);

        // Assert
        assertEquals(expectedIncome, doctor.getIncome());
    }

    @Test
    @DisplayName("setDocId with null value")
    void testSetDocId_withNull() {
        // Arrange
        doctor.setDocId(100);

        // Act
        doctor.setDocId(null);

        // Assert
        assertNull(doctor.getDocId());
    }

    @Test
    @DisplayName("setDocName with null value")
    void testSetDocName_withNull() {
        // Arrange
        doctor.setDocName("SomeName");

        // Act
        doctor.setDocName(null);

        // Assert
        assertNull(doctor.getDocName());
    }

    @Test
    @DisplayName("setSpecialization with null value")
    void testSetSpecialization_withNull() {
        // Arrange
        doctor.setSpecialization("Cardio");

        // Act
        doctor.setSpecialization(null);

        // Assert
        assertNull(doctor.getSpecialization());
    }

    @Test
    @DisplayName("setIncome with null value")
    void testSetIncome_withNull() {
        // Arrange
        doctor.setIncome(50000.00);

        // Act
        doctor.setIncome(null);

        // Assert
        assertNull(doctor.getIncome());
    }

    @Test
    @DisplayName("setIncome with zero value")
    void testSetIncome_withZero() {
        // Arrange & Act
        doctor.setIncome(0.0);

        // Assert
        assertEquals(0.0, doctor.getIncome());
    }

    @Test
    @DisplayName("setIncome with negative value")
    void testSetIncome_withNegativeValue() {
        // Arrange & Act
        doctor.setIncome(-1000.00);

        // Assert
        assertEquals(-1000.00, doctor.getIncome());
    }

    @Test
    @DisplayName("setDocName with empty string")
    void testSetDocName_withEmptyString() {
        // Arrange & Act
        doctor.setDocName("");

        // Assert
        assertEquals("", doctor.getDocName());
    }

    @Test
    @DisplayName("setSpecialization with empty string")
    void testSetSpecialization_withEmptyString() {
        // Arrange & Act
        doctor.setSpecialization("");

        // Assert
        assertEquals("", doctor.getSpecialization());
    }

    @Test
    @DisplayName("setDocId with negative value")
    void testSetDocId_withNegativeValue() {
        // Arrange & Act
        doctor.setDocId(-1);

        // Assert
        assertEquals(-1, doctor.getDocId());
    }

    @Test
    @DisplayName("setDocId with zero value")
    void testSetDocId_withZero() {
        // Arrange & Act
        doctor.setDocId(0);

        // Assert
        assertEquals(0, doctor.getDocId());
    }

    // ─── Equals and HashCode Tests (Lombok @Data) ────────────────────────────

    @Test
    @DisplayName("Two doctors with same fields are equal")
    void testEquals_withSameFields_returnsTrue() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setDocName("sairam");
        doc1.setSpecialization("MD_Cardio");
        doc1.setIncome(90000.00);

        Doctor doc2 = new Doctor();
        doc2.setDocId(1);
        doc2.setDocName("sairam");
        doc2.setSpecialization("MD_Cardio");
        doc2.setIncome(90000.00);

        // Act & Assert
        assertEquals(doc1, doc2);
    }

    @Test
    @DisplayName("Two doctors with different IDs are not equal")
    void testEquals_withDifferentIds_returnsFalse() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setDocName("sairam");

        Doctor doc2 = new Doctor();
        doc2.setDocId(2);
        doc2.setDocName("sairam");

        // Act & Assert
        assertNotEquals(doc1, doc2);
    }

    @Test
    @DisplayName("Doctor is not equal to null")
    void testEquals_withNull_returnsFalse() {
        // Arrange
        Doctor doc = new Doctor();
        doc.setDocId(1);

        // Act & Assert
        assertNotEquals(null, doc);
    }

    @Test
    @DisplayName("Doctor is equal to itself (reflexive)")
    void testEquals_withSameReference_returnsTrue() {
        // Arrange
        Doctor doc = new Doctor();
        doc.setDocId(1);
        doc.setDocName("sairam");

        // Act & Assert
        assertEquals(doc, doc);
    }

    @Test
    @DisplayName("Two doctors with same fields have same hashCode")
    void testHashCode_withSameFields_returnsSameHash() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setDocName("sairam");
        doc1.setSpecialization("MD_Cardio");
        doc1.setIncome(90000.00);

        Doctor doc2 = new Doctor();
        doc2.setDocId(1);
        doc2.setDocName("sairam");
        doc2.setSpecialization("MD_Cardio");
        doc2.setIncome(90000.00);

        // Act & Assert
        assertEquals(doc1.hashCode(), doc2.hashCode());
    }

    @Test
    @DisplayName("Two doctors with different fields have different hashCodes")
    void testHashCode_withDifferentFields_returnsDifferentHash() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setDocName("sairam");

        Doctor doc2 = new Doctor();
        doc2.setDocId(2);
        doc2.setDocName("john");

        // Act & Assert
        assertNotEquals(doc1.hashCode(), doc2.hashCode());
    }

    @Test
    @DisplayName("Two doctors with different names are not equal")
    void testEquals_withDifferentNames_returnsFalse() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setDocName("sairam");

        Doctor doc2 = new Doctor();
        doc2.setDocId(1);
        doc2.setDocName("john");

        // Act & Assert
        assertNotEquals(doc1, doc2);
    }

    @Test
    @DisplayName("Two doctors with different specializations are not equal")
    void testEquals_withDifferentSpecializations_returnsFalse() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setSpecialization("Cardio");

        Doctor doc2 = new Doctor();
        doc2.setDocId(1);
        doc2.setSpecialization("Neuro");

        // Act & Assert
        assertNotEquals(doc1, doc2);
    }

    @Test
    @DisplayName("Two doctors with different incomes are not equal")
    void testEquals_withDifferentIncomes_returnsFalse() {
        // Arrange
        Doctor doc1 = new Doctor();
        doc1.setDocId(1);
        doc1.setIncome(90000.00);

        Doctor doc2 = new Doctor();
        doc2.setDocId(1);
        doc2.setIncome(80000.00);

        // Act & Assert
        assertNotEquals(doc1, doc2);
    }

    // ─── toString Tests (Lombok @Data) ───────────────────────────────────────

    @Test
    @DisplayName("toString returns non-null string")
    void testToString_returnsNonNull() {
        // Arrange
        doctor.setDocId(1);
        doctor.setDocName("sairam");

        // Act
        String result = doctor.toString();

        // Assert
        assertNotNull(result);
    }

    @Test
    @DisplayName("toString contains docId value")
    void testToString_containsDocId() {
        // Arrange
        doctor.setDocId(101);
        doctor.setDocName("sairam");

        // Act
        String result = doctor.toString();

        // Assert
        assertTrue(result.contains("101"));
    }

    @Test
    @DisplayName("toString contains docName value")
    void testToString_containsDocName() {
        // Arrange
        doctor.setDocId(1);
        doctor.setDocName("sairam");

        // Act
        String result = doctor.toString();

        // Assert
        assertTrue(result.contains("sairam"));
    }

    @Test
    @DisplayName("toString contains specialization value")
    void testToString_containsSpecialization() {
        // Arrange
        doctor.setDocId(1);
        doctor.setSpecialization("MD_Cardio");

        // Act
        String result = doctor.toString();

        // Assert
        assertTrue(result.contains("MD_Cardio"));
    }

    @Test
    @DisplayName("toString contains income value")
    void testToString_containsIncome() {
        // Arrange
        doctor.setDocId(1);
        doctor.setIncome(90000.0);

        // Act
        String result = doctor.toString();

        // Assert
        assertTrue(result.contains("90000.0"));
    }

    @Test
    @DisplayName("toString is not empty")
    void testToString_isNotEmpty() {
        // Act
        String result = doctor.toString();

        // Assert
        assertFalse(result.isEmpty());
    }

    // ─── Full Object Population Test ─────────────────────────────────────────

    @Test
    @DisplayName("Fully populated Doctor has all fields set correctly")
    void testFullyPopulatedDoctor() {
        // Arrange
        Integer id = 203;
        String name = "sairam";
        String spec = "MD_Cardio";
        Double income = 90000.00;

        // Act
        doctor.setDocId(id);
        doctor.setDocName(name);
        doctor.setSpecialization(spec);
        doctor.setIncome(income);

        // Assert
        assertAll("Doctor fields",
                () -> assertEquals(id, doctor.getDocId()),
                () -> assertEquals(name, doctor.getDocName()),
                () -> assertEquals(spec, doctor.getSpecialization()),
                () -> assertEquals(income, doctor.getIncome())
        );
    }

    @Test
    @DisplayName("Doctor fields can be updated after initial set")
    void testDoctorFields_canBeUpdated() {
        // Arrange
        doctor.setDocId(1);
        doctor.setDocName("OldName");

        // Act
        doctor.setDocName("NewName");

        // Assert
        assertEquals("NewName", doctor.getDocName());
    }

    @Test
    @DisplayName("Doctor with large income value")
    void testSetIncome_withLargeValue() {
        // Arrange & Act
        doctor.setIncome(Double.MAX_VALUE);

        // Assert
        assertEquals(Double.MAX_VALUE, doctor.getIncome());
    }

    @Test
    @DisplayName("Doctor with max integer docId")
    void testSetDocId_withMaxInteger() {
        // Arrange & Act
        doctor.setDocId(Integer.MAX_VALUE);

        // Assert
        assertEquals(Integer.MAX_VALUE, doctor.getDocId());
    }

    @Test
    @DisplayName("Doctor with min integer docId")
    void testSetDocId_withMinInteger() {
        // Arrange & Act
        doctor.setDocId(Integer.MIN_VALUE);

        // Assert
        assertEquals(Integer.MIN_VALUE, doctor.getDocId());
    }

    @Test
    @DisplayName("Doctor income with small decimal value")
    void testSetIncome_withSmallDecimalValue() {
        // Arrange & Act
        doctor.setIncome(0.001);

        // Assert
        assertEquals(0.001, doctor.getIncome(), 0.0001);
    }

    @Test
    @DisplayName("Two default doctors are equal")
    void testEquals_twoDefaultDoctors_areEqual() {
        // Arrange
        Doctor doc1 = new Doctor();
        Doctor doc2 = new Doctor();

        // Act & Assert
        assertEquals(doc1, doc2);
    }

    @Test
    @DisplayName("Doctor class name is correct")
    void testDoctorClass_hasCorrectName() {
        // Assert
        assertEquals("com.sit.entity.Doctor", Doctor.class.getName());
    }

    @Test
    @DisplayName("Doctor specialization with special characters")
    void testSetSpecialization_withSpecialCharacters() {
        // Arrange & Act
        doctor.setSpecialization("MD_Cardio-Vascular");

        // Assert
        assertEquals("MD_Cardio-Vascular", doctor.getSpecialization());
    }

    @Test
    @DisplayName("Doctor name with spaces")
    void testSetDocName_withSpaces() {
        // Arrange & Act
        doctor.setDocName("Dr. John Smith");

        // Assert
        assertEquals("Dr. John Smith", doctor.getDocName());
    }
}
